<?php namespace App\Controllers; use CodeIgniter\Controller; use App\Models\JobModel; class TestInsert extends Controller { public function index() { $jobModel = new JobModel(); $jobModel->skipValidation(true); $data = ["employer_id" => 1, "category_id" => 17, "title" => "test title", "slug" => "test-title", "description" => "test description test description test description test description test description test description test description test description test description test description test description test description", "is_urgent" => 1, "status" => "draft", "admin_status" => "pending"]; try { $result = $jobModel->insert($data); if (!$result) { echo "Insert returned false. Errors: " . json_encode($jobModel->errors()) . "<br>"; $db = \Config\Database::connect(); $error = $db->error(); echo "DB Error: " . json_encode($error); } else { echo "Insert success ID: " . $result; } } catch (\Exception $e) { echo "Exception: " . $e->getMessage(); } } }
